<?php require_once __DIR__.'/_base.php'; $title='Verification'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $pid=$pdo->query('SELECT id FROM providers WHERE user_id='.(int)$u['id'])->fetchColumn();$p=$pdo->query('SELECT verification_status FROM providers WHERE id='.(int)$pid)->fetch();$docs=$pdo->prepare('SELECT * FROM provider_documents WHERE provider_id=? ORDER BY uploaded_at DESC');$docs->execute([$pid]);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$type=post('document_type');if(isset($_FILES['document'])&&$_FILES['document']['error']===UPLOAD_ERR_OK){$allowed=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];$ext=strtolower(pathinfo($_FILES['document']['name'],PATHINFO_EXTENSION));if(isset($allowed[$ext])&&$_FILES['document']['size']<=5*1024*1024){$name=bin2hex(random_bytes(12)).'.'.$ext;$dest=__DIR__.'/../uploads/documents/'.$name;move_uploaded_file($_FILES['document']['tmp_name'],$dest);$pdo->prepare('INSERT INTO provider_documents(provider_id,document_type,document_path,verification_status) VALUES(?,?,?,?)')->execute([$pid,$type,'uploads/documents/'.$name,'Pending']);$pdo->prepare("UPDATE providers SET verification_status='Pending' WHERE id=?")->execute([$pid]);flash('success','Document uploaded for admin review.');redirect('verification.php');}else{$err='Allowed files: PDF/JPG/JPEG/PNG up to 5MB.';}}}?><div class="row g-4"><div class="col-lg-5"><div class="service-card p-4"><h3>Verification</h3><p>Status: <?=badge($p['verification_status'])?></p><?php if(!empty($err)):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><select name="document_type" class="form-select mb-3"><option>CNIC</option><option>Experience Certificate</option><option>Other</option></select><input type="file" name="document" class="form-control mb-3" accept=".pdf,.jpg,.jpeg,.png" required><button class="btn btn-success">Upload</button></form></div></div><div class="col-lg-7"><div class="service-card p-4"><h4>Uploaded documents</h4><?php foreach($docs->fetchAll() as $d):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e($d['document_type'])?></span><?=badge($d['verification_status'])?></div><?php endforeach;?></div></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>